"""Installs a tiny keyconfig preset ("Blaya.py") that loads ``keymap.py`` from this folder.

Blender only loads key configurations from preset files, and it may do so before add-ons are
registered, so the preset loads ``keymap.py`` by file path instead of importing the add-on.
"""

import os

import bpy

KEYCONFIG_NAME = "Blaya"

_STUB = '''\
# Generated by the Blaya add-on. Do not edit: it is rewritten when the add-on loads.
# It loads the real keymap from the add-on folder.
import importlib.util
import os

KEYMAP_FILE = {path!r}

if __name__ == "__main__":
    if os.path.exists(KEYMAP_FILE):
        _spec = importlib.util.spec_from_file_location("blaya_keymap", KEYMAP_FILE)
        _mod = importlib.util.module_from_spec(_spec)
        _spec.loader.exec_module(_mod)
        _mod.load({name!r})
    else:
        print("Blaya: keymap file not found:", KEYMAP_FILE)
'''


def preset_path():
    folder = bpy.utils.user_resource('SCRIPTS', path=os.path.join("presets", "keyconfig"), create=True)
    return os.path.join(folder, KEYCONFIG_NAME + ".py")


def ensure_preset():
    """Write or refresh the preset stub. Returns its path."""
    keymap_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "keymap.py")
    text = _STUB.format(path=keymap_file, name=KEYCONFIG_NAME)
    path = preset_path()
    try:
        with open(path, encoding="utf-8") as fh:
            if fh.read() == text:
                return path
    except OSError:
        pass
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(text)
    return path
